const input = $input.first().json;
const columns = ['review_key','offer_key','declared_company_name','declared_city','reason','top_margin','candidate_rank','candidate_siret','candidate_siren','candidate_name','candidate_city','total_score','score_dimensions_json','decision','selected_siret','reviewer','review_note'];
const export_rows = (input.review_rows || []).flatMap((row) => (row.candidates || []).map((c, i) => ({ review_key: row.review_key, offer_key: row.offer_key, declared_company_name: row.declared_company_name || '', declared_city: row.declared_city || '', reason: row.reason, top_margin: row.top_margin, candidate_rank: i + 1, candidate_siret: c.siret || '', candidate_siren: c.siren || '', candidate_name: c.legal_name || c.trade_name || '', candidate_city: c.city || '', total_score: c.total_score || '', score_dimensions_json: JSON.stringify(c.score_dimensions || {}), decision: '', selected_siret: '', reviewer: '', review_note: '' })));
return [{ json: { ...input, csv_columns: columns, export_rows } }];

const input = $input.first().json;
const allowed = new Set(['accept','reject','select_siret','ignore']);
const candidateSirets = new Map((input.review_rows || []).map((row) => [row.review_key, new Set((row.candidates || []).map((c) => c.siret).filter(Boolean))]));
const accepted = []; const rejected = [];
for (const row of input.imported_decisions || []) {
  const decision = String(row.decision || '').trim();
  const selected = String(row.selected_siret || '').replace(/\D/g, '');
  const key = `${row.review_key}:${decision}:${selected}:${row.reviewer || ''}`;
  let error = null;
  if (!row.review_key || !allowed.has(decision)) error = 'G8N_REVIEW_INVALID_DECISION';
  else if (input.previous_decision_keys.includes(key)) error = 'G8N_REVIEW_DUPLICATE_DECISION';
  else if (decision === 'select_siret' && selected.length !== 14) error = 'G8N_REVIEW_INVALID_SIRET';
  else if (decision === 'select_siret' && !candidateSirets.get(row.review_key)?.has(selected) && !row.review_note) error = 'G8N_REVIEW_OVERRIDE_NOTE_REQUIRED';
  if (error === 'G8N_REVIEW_DUPLICATE_DECISION') rejected.push({ ...row, status: 'duplicate_ignored', error_code: error });
  else if (error) rejected.push({ ...row, status: 'rejected', error_code: error });
  else accepted.push({ ...row, status: 'accepted', decision_key: key, reviewed_at: input.now_utc, invalidate_downstream: ['company_signals','lead_scores','exports'] });
}
return [{ json: { ...input, import_report: { accepted_count: accepted.length, rejected_count: rejected.length, accepted, rejected } } }];
